use super::common::{
    Leaf, env_name_literal, format_scalar_literal, has_env_refs, is_valid_identifier, kind_name,
    leaf_of, single_kind,
};
use super::tree::{ConfigNode, build_config_tree};
use crate::error::Result;
use crate::model::{ResolvedSetting, TypeShape, ValueKind};
use indexmap::IndexMap;
use toml::Value as TomlValue;

pub fn generate_haskell(settings: &[ResolvedSetting]) -> Result<String> {
    let tree = build_config_tree(settings, false);
    let mut out = String::from(
        "{-# LANGUAGE DuplicateRecordFields #-}\n\n-- Generated by SettingSpec\n\nmodule Settings where\n\n",
    );
    if has_env_refs(settings) {
        out.push_str("import System.Environment (getEnv, lookupEnv)\n\n");
    }

    let mut data_defs = String::new();
    let root_type =
        generate_haskell_data_types(&tree, "Settings", !has_env_refs(settings), &mut data_defs);
    out.push_str(&data_defs);

    let mut val_body = String::new();
    format_haskell_record_val(&tree, "Settings", 1, &mut val_body);

    out.push_str(&format!(
        "settings :: {}\nsettings = {}\n",
        root_type, val_body
    ));

    Ok(out)
}

/// `derive` is false if a record has `IO` fields, which cannot be shown or
/// compared.
fn generate_haskell_data_types(
    map: &IndexMap<String, ConfigNode>,
    type_name: &str,
    derive: bool,
    out: &mut String,
) -> String {
    let mut fields = Vec::new();

    for (k, node) in map {
        let field_name = sanitize_haskell_identifier(k);
        match node {
            ConfigNode::Typed(shape, _) => {
                let sum_name = format!("{}{}Value", type_name, capitalize(k));
                if single_kind(shape).is_none() {
                    out.push_str(&haskell_sum_type(&sum_name, shape));
                }
                fields.push(format!(
                    "  , {} :: {}",
                    field_name,
                    haskell_typed_type(shape, &sum_name)
                ));
            }
            ConfigNode::Null | ConfigNode::Env(_) => {
                unreachable!("nulls and environment references are always typed")
            }
            ConfigNode::Value(v) => match v {
                TomlValue::String(_) | TomlValue::Datetime(_) => {
                    fields.push(format!("  , {} :: String", field_name));
                }
                TomlValue::Integer(_) => {
                    fields.push(format!("  , {} :: Int", field_name));
                }
                TomlValue::Float(_) => {
                    fields.push(format!("  , {} :: Double", field_name));
                }
                TomlValue::Boolean(_) => {
                    fields.push(format!("  , {} :: Bool", field_name));
                }
                TomlValue::Array(arr) => {
                    let type_str = haskell_list_type(arr);
                    fields.push(format!("  , {} :: {}", field_name, type_str));
                }
                TomlValue::Table(tbl) => {
                    let sub_name = format!("{}{}", type_name, capitalize(k));
                    let mut sub_map = IndexMap::new();
                    for (sub_k, sub_v) in tbl {
                        sub_map.insert(sub_k.clone(), ConfigNode::Value(sub_v.clone()));
                    }
                    let sub_type = generate_haskell_data_types(&sub_map, &sub_name, derive, out);
                    fields.push(format!("  , {} :: {}", field_name, sub_type));
                }
            },
            ConfigNode::Map(sub_map) => {
                let sub_name = format!("{}{}", type_name, capitalize(k));
                let sub_type = generate_haskell_data_types(sub_map, &sub_name, derive, out);
                fields.push(format!("  , {} :: {}", field_name, sub_type));
            }
        }
    }

    let deriving = if derive { " deriving (Show, Eq)" } else { "" };
    let field_block = if fields.is_empty() {
        format!("data {} = {}{}\n\n", type_name, type_name, deriving)
    } else {
        // Change the first comma into a brace
        let mut first = true;
        let mut formatted_fields = Vec::new();
        for f in fields {
            if first {
                first = false;
                formatted_fields.push(format!("  {{ {}", &f[4..]));
            } else {
                formatted_fields.push(f);
            }
        }
        format!(
            "data {} = {}\n{}\n  }}{}\n\n",
            type_name,
            type_name,
            formatted_fields.join("\n"),
            deriving
        )
    };

    out.push_str(&field_block);
    type_name.to_string()
}

fn format_haskell_record_val(
    map: &IndexMap<String, ConfigNode>,
    constructor: &str,
    indent_level: usize,
    out: &mut String,
) {
    let indent = "    ".repeat(indent_level);

    if map.is_empty() {
        out.push_str(constructor);
        return;
    }

    out.push_str(&format!("{}\n{}  {{ ", constructor, indent));

    let mut first = true;
    for (k, node) in map {
        let field_name = sanitize_haskell_identifier(k);
        let prefix = if first {
            first = false;
            String::new()
        } else {
            format!("\n{}  , ", indent)
        };

        match node {
            ConfigNode::Typed(shape, inner) => {
                let sum_name = format!("{}{}Value", constructor, capitalize(k));
                out.push_str(&format!(
                    "{}{} = {}",
                    prefix,
                    field_name,
                    haskell_typed_value(shape, &sum_name, inner)
                ));
            }
            ConfigNode::Null | ConfigNode::Env(_) => {
                unreachable!("nulls and environment references are always typed")
            }
            ConfigNode::Value(v) => match v {
                TomlValue::Table(tbl) => {
                    let sub_constructor = format!("{}{}", constructor, capitalize(k));
                    out.push_str(&format!("{}{} = ", prefix, field_name));
                    let mut sub_map = IndexMap::new();
                    for (sub_k, sub_v) in tbl {
                        sub_map.insert(sub_k.clone(), ConfigNode::Value(sub_v.clone()));
                    }
                    format_haskell_record_val(&sub_map, &sub_constructor, indent_level + 1, out);
                }
                _ => {
                    out.push_str(&format!(
                        "{}{} = {}",
                        prefix,
                        field_name,
                        toml_to_haskell_literal(v)
                    ));
                }
            },
            ConfigNode::Map(sub_map) => {
                let sub_constructor = format!("{}{}", constructor, capitalize(k));
                out.push_str(&format!("{}{} = ", prefix, field_name));
                format_haskell_record_val(sub_map, &sub_constructor, indent_level + 1, out);
            }
        }
    }
    out.push_str(&format!("\n{}  }}", indent));
}

fn haskell_list_type(arr: &[TomlValue]) -> &'static str {
    if arr.is_empty() {
        return "[String]";
    }
    match &arr[0] {
        TomlValue::Integer(_) => "[Int]",
        TomlValue::Float(_) => "[Double]",
        TomlValue::Boolean(_) => "[Bool]",
        _ => "[String]",
    }
}

fn sanitize_haskell_identifier(name: &str) -> String {
    let is_keyword = matches!(
        name,
        "as" | "case"
            | "of"
            | "class"
            | "data"
            | "default"
            | "deriving"
            | "do"
            | "forall"
            | "foreign"
            | "hiding"
            | "if"
            | "then"
            | "else"
            | "import"
            | "infix"
            | "infixl"
            | "infixr"
            | "instance"
            | "let"
            | "in"
            | "mdo"
            | "module"
            | "newtype"
            | "qualified"
            | "type"
            | "where"
    );

    if is_keyword {
        format!("{}_", name)
    } else if is_valid_identifier(name) && name.chars().next().unwrap().is_ascii_lowercase() {
        name.to_string()
    } else {
        let clean = name.replace(|c: char| !c.is_ascii_alphanumeric(), "_");
        let mut chars = clean.chars();
        match chars.next() {
            None => "setting".to_string(),
            Some(first) => {
                if first.is_ascii_digit() || first == '_' {
                    format!("k_{}", clean)
                } else {
                    format!("{}{}", first.to_ascii_lowercase(), chars.as_str())
                }
            }
        }
    }
}

fn capitalize(s: &str) -> String {
    let mut c = s.chars();
    match c.next() {
        None => String::new(),
        Some(f) => f.to_uppercase().collect::<String>() + c.as_str(),
    }
}

fn haskell_kind_type(kind: ValueKind) -> &'static str {
    match kind {
        ValueKind::String => "String",
        ValueKind::Integer => "Int",
        ValueKind::Float => "Double",
        ValueKind::Boolean => "Bool",
        ValueKind::Array | ValueKind::Table => unreachable!("rejected before formatting"),
    }
}

/// `data` declaration of the sum type of a setting with several kinds.
fn haskell_sum_type(name: &str, shape: &TypeShape) -> String {
    let mut ctors: Vec<String> = shape
        .kinds
        .iter()
        .map(|k| format!("{}{} {}", name, kind_name(*k), haskell_kind_type(*k)))
        .collect();
    if shape.nullable {
        ctors.push(format!("{}Null", name));
    }
    format!(
        "data {} = {}\n  deriving (Show, Eq)\n\n",
        name,
        ctors.join("\n  | ")
    )
}

/// The field type of a setting whose type is shared by all profiles; `IO` if
/// it reads the environment.
fn haskell_typed_type(shape: &TypeShape, sum_name: &str) -> String {
    let base = match single_kind(shape) {
        Some(k) if shape.nullable => format!("Maybe {}", haskell_kind_type(k)),
        Some(k) => haskell_kind_type(k).to_string(),
        None => sum_name.to_string(),
    };
    if shape.has_env && base.contains(' ') {
        format!("IO ({})", base)
    } else if shape.has_env {
        format!("IO {}", base)
    } else {
        base
    }
}

fn haskell_typed_value(shape: &TypeShape, sum_name: &str, inner: &ConfigNode) -> String {
    let single = single_kind(shape).is_some();
    let pure = |expr: String| {
        if shape.has_env {
            format!("pure ({})", expr)
        } else {
            expr
        }
    };
    match leaf_of(inner) {
        Some(Leaf::Value(v)) => {
            let lit = toml_to_haskell_literal(v);
            let expr = if single && shape.nullable {
                format!("Just ({})", lit)
            } else if single {
                lit
            } else {
                format!("{}{} ({})", sum_name, kind_name(ValueKind::of(v)), lit)
            };
            pure(expr)
        }
        Some(Leaf::Env(r)) => {
            let name = env_name_literal(&r.name);
            match (single, shape.nullable) {
                (true, true) => format!("lookupEnv {}", name),
                (true, false) => format!("getEnv {}", name),
                (false, true) => format!(
                    "fmap (maybe {}Null {}Str) (lookupEnv {})",
                    sum_name, sum_name, name
                ),
                (false, false) => format!("fmap {}Str (getEnv {})", sum_name, name),
            }
        }
        _ if single => pure("Nothing".to_string()),
        _ => pure(format!("{}Null", sum_name)),
    }
}

fn toml_to_haskell_literal(v: &TomlValue) -> String {
    if let Some(literal) = format_scalar_literal(v) {
        return literal;
    }
    match v {
        TomlValue::Boolean(b) => {
            if *b {
                "True".to_string()
            } else {
                "False".to_string()
            }
        }
        TomlValue::Array(arr) => {
            let items: Vec<String> = arr.iter().map(toml_to_haskell_literal).collect();
            format!("[{}]", items.join(", "))
        }
        _ => "\"\"".to_string(),
    }
}
